// ConsumerDependency, AnalysisRun, CompatibilityChange, ImpactFinding,
// PublishAttempt) are added in later increments, one per feature module.

model Service {
  id          String   @id @default(uuid())
  name        String   @unique
  owner       String
  description String?
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt
}

