  try {
    await pg.createDatabase(name);
  } catch (err) {
    if (!/already exists/i.test(String(err.message ?? err))) throw err;
  }
}

await createDatabaseIfMissing('contractguard');
await createDatabaseIfMissing('contractguard_test');

