// Throwaway probe: pins down @apidevtools/swagger-parser behavior.
import { readFileSync } from 'node:fs';
import SwaggerParser from '@apidevtools/swagger-parser';

const root = new URL('..', import.meta.url);

async function probe(label, fn) {
  try {
    const out = await fn();
    console.log(`=== ${label}: OK`);
    console.log('  keys:', out && typeof out === 'object' ? Object.keys(out).slice(0, 8) : typeof out);
    console.log('  openapi:', out && out.openapi, '| paths:', out && out.paths ? Object.keys(out.paths) : '-');
  } catch (err) {
    console.log(`=== ${label}: THREW ${err.name} / ${err.constructor.name}`);
    console.log('  message:', err.message);
    console.log('  code:', err.code);
    console.log('  has errors array:', Array.isArray(err.errors), err.errors ? err.errors.length : '');
    if (Array.isArray(err.errors)) {
      for (const e of err.errors.slice(0, 5)) {
        console.log('  err:', JSON.stringify({
          message: e.message,
          instancePath: e.instancePath,
          schemaPath: e.schemaPath,
          keyword: e.keyword,
          params: e.params,
        }));
      }
    }
    console.log('  own props:', Object.keys(err));
  }
}

