    if (!toEntry) {
      changes.push(makeChange('ENDPOINT_REMOVED', { path: fromEntry.originalPath, location: 'endpoint', method: null, before: { methods: [...] }, after: null }));
      continue;
    }

    const methods = union of method keys;
    for (const method of sortedByMethodOrder(methods)) {
      const fromOp = fromEntry.methods.get(method);
      const toOp = toEntry.methods.get(method);
      if (!fromOp && toOp) {
        changes.push(makeChange('METHOD_ADDED', { method, path: toEntry.originalPath, location: 'method', before: null, after: null }));
        continue;
