    const [status, contentType] = detail.includes('[') ? [detail.slice(0, detail.indexOf('[')), detail.slice(detail.indexOf('[') + 1, -1)] : [detail, null];
    return contentType ? `the response (${status}, ${contentType}) schema` : `the response (${status}) schema`;
  }
  return 'the operation';
}
