// Compatibility Classification — deterministic, rule-based engine.
//
// Pure module — no database, no Express, no LLM. Takes the structural change
// list produced by spec-comparator and classifies each change as
// BREAKING / NON_BREAKING / UNKNOWN, with a plain-language explanation for
// every classification. The same input always produces the same output.
//
// Initial rule set (per change type, as implemented):
//
//   Operations
//     ENDPOINT_REMOVED, METHOD_REMOVED            -> BREAKING
//     ENDPOINT_ADDED, METHOD_ADDED                -> NON_BREAKING
//     OPERATION_ID_CHANGED                        -> UNKNOWN (no rule defined)
//
//   Request parameters
//     PARAMETER_REMOVED                           -> BREAKING
//     PARAMETER_ADDED (required)                  -> BREAKING
//     PARAMETER_ADDED (optional)                  -> NON_BREAKING
//     PARAMETER_REQUIREDNESS_CHANGED (opt->req)   -> BREAKING
//     PARAMETER_REQUIREDNESS_CHANGED (req->opt)   -> NON_BREAKING
//     PARAMETER_TYPE_CHANGED                      -> BREAKING
//     PARAMETER_ENUM_CHANGED (values removed)     -> BREAKING
//     PARAMETER_ENUM_CHANGED (values added)       -> NON_BREAKING
//
//   Request body
//     REQUEST_BODY_REMOVED                        -> BREAKING
//     REQUEST_BODY_REQUIREDNESS_CHANGED (opt->req)-> BREAKING
//     REQUEST_BODY_REQUIREDNESS_CHANGED (req->opt)-> NON_BREAKING
//     REQUEST_BODY_ADDED                          -> UNKNOWN (no rule defined)
//     REQUEST_CONTENT_TYPE_ADDED / _REMOVED       -> UNKNOWN (no rule defined)
//     FIELD_ADDED, request (required)             -> BREAKING
//     FIELD_ADDED, request (optional)             -> NON_BREAKING
//     FIELD_REMOVED, request                      -> BREAKING
//     FIELD_TYPE_CHANGED, request                 -> BREAKING
//     FIELD_REQUIREDNESS_CHANGED, request (->req) -> BREAKING
//       (direction rule carried over from the parameter requiredness rules)
//     FIELD_REQUIREDNESS_CHANGED, request (->opt) -> NON_BREAKING
//     ENUM_CHANGED, request (values removed)      -> BREAKING
//     ENUM_CHANGED, request (values added only)   -> NON_BREAKING
//
//   Response
//     RESPONSE_STATUS_ADDED                       -> NON_BREAKING
//     RESPONSE_STATUS_REMOVED                     -> UNKNOWN
//     RESPONSE_CONTENT_TYPE_ADDED / _REMOVED      -> UNKNOWN
//     FIELD_ADDED, response (optional)            -> NON_BREAKING
//     FIELD_ADDED, response (required)            -> UNKNOWN
//     FIELD_REMOVED, response                     -> BREAKING
//     FIELD_TYPE_CHANGED, response                -> BREAKING
//     FIELD_REQUIREDNESS_CHANGED, response        -> UNKNOWN (no rule defined)
//     ENUM_CHANGED, response (any direction)      -> UNKNOWN
//
//   Not covered by the initial rule set (never guessed, always UNKNOWN):
//     NULLABLE_CHANGED, CONSTRAINT_CHANGED, and any change type that is
//     added to the comparator later without a rule here.
//
// Overall verdict for a change set:
//   NO_CHANGES    — no changes at all
//   BREAKING      — at least one BREAKING change
//   UNKNOWN       — no BREAKING, but at least one UNKNOWN
//   NON_BREAKING  — changes exist and all are NON_BREAKING

export const COMPATIBILITY = {
  BREAKING: 'BREAKING',
  NON_BREAKING: 'NON_BREAKING',
  UNKNOWN: 'UNKNOWN',
};

export const OVERALL_VERDICTS = {
  NO_CHANGES: 'NO_CHANGES',
  BREAKING: 'BREAKING',
  NON_BREAKING: 'NON_BREAKING',
  UNKNOWN: 'UNKNOWN',
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function breaking(explanation) {
  return { compatibility: COMPATIBILITY.BREAKING, explanation };
}

function nonBreaking(explanation) {
  return { compatibility: COMPATIBILITY.NON_BREAKING, explanation };
}

function unknown(explanation) {
  return { compatibility: COMPATIBILITY.UNKNOWN, explanation };
}

// Symmetric difference of two enum value lists.
function enumDiff(before, after) {
  const beforeValues = new Set(before ?? []);
  const afterValues = new Set(after ?? []);
  return {
    removed: [...beforeValues].filter((value) => !afterValues.has(value)),
    added: [...afterValues].filter((value) => !beforeValues.has(value)),
  };
}

function valuesPhrase(values) {
  return values.length === 0 ? 'none' : `[${values.join(', ')}]`;
}

function isResponseLocation(location) {
  return typeof location === 'string' && location.startsWith('response.');
}

// Last field segment: request.premium -> premium, response.200.items[].amount
// -> amount.
function fieldLeaf(fieldPath) {
  const leaf = String(fieldPath ?? '').split('.').pop();
  return leaf.endsWith('[]') ? leaf.slice(0, -2) : leaf;
}

function wherePhrase(change) {
  return change.method ? `${change.method} ${change.path}` : change.path ?? 'the specification';
}

// The response status a change refers to (from the fieldPath or location).
function statusOf(change) {
  if (typeof change.fieldPath === 'string' && change.fieldPath.startsWith('response.')) {
    return change.fieldPath.slice('response.'.length).split(/[.[\]]/)[0];
  }
  if (isResponseLocation(change.location)) {
    return change.location.slice('response.'.length);
  }
  return 'unknown';
}

function typePhrase(descriptor) {
  if (!descriptor || typeof descriptor !== 'object') return 'unknown';
  const type = descriptor.type ?? 'any';
  return descriptor.format ? `${type} (${descriptor.format})` : type;
}

// ---------------------------------------------------------------------------
// Classification
// ---------------------------------------------------------------------------

/**
 * Classify one structural change.
 *
 * @param {object} change a change produced by spec-comparator
 * @returns {{ compatibility: string, explanation: string }}
 */
export function classifyChange(change) {
  const { changeType } = change;
  const where = wherePhrase(change);
  const field = change.fieldPath ? fieldLeaf(change.fieldPath) : '';
  const inResponse = isResponseLocation(change.location);

  switch (changeType) {
    // ------------------------------------------------------------------
    // Operations
    // ------------------------------------------------------------------
    case 'ENDPOINT_REMOVED':
      return breaking(
        `Endpoint ${change.path} (methods: ${change.before.methods.join(', ')}) was removed. Any existing client that calls this endpoint will no longer reach it.`
      );
    case 'METHOD_REMOVED':
      return breaking(
        `${change.method} ${change.path} was removed. Existing clients that call this operation will receive 404/405 responses.`
      );
    case 'ENDPOINT_ADDED':
      return nonBreaking(
        `Endpoint ${change.path} (methods: ${change.after.methods.join(', ')}) was added. New surface area cannot affect existing clients.`
      );
    case 'METHOD_ADDED':
      return nonBreaking(
        `${change.method} ${change.path} was added. New surface area cannot affect existing clients.`
      );
    case 'OPERATION_ID_CHANGED':
      return unknown(
        `operationId changed from "${change.before.operationId}" to "${change.after.operationId}" on ${where}. The initial rule set defines no rule for operationId changes; generated clients may depend on it, so manual review is recommended.`
      );

    // ------------------------------------------------------------------
    // Request parameters
    // ------------------------------------------------------------------
    case 'PARAMETER_REMOVED':
      return breaking(
        `Parameter "${change.before.name}" (${change.before.in}) was removed from ${where}. Clients that send this parameter may be rejected or have it ignored.`
      );
    case 'PARAMETER_ADDED':
      return change.after.required
        ? breaking(
            `Required parameter "${change.after.name}" (${change.after.in}) was added to ${where}. Existing clients that do not send it will be rejected.`
          )
        : nonBreaking(
            `Optional parameter "${change.after.name}" (${change.after.in}) was added to ${where}. Clients that do not send it are unaffected.`
          );
    case 'PARAMETER_REQUIREDNESS_CHANGED':
      return change.after.required
        ? breaking(
            `Parameter "${field}" on ${where} became required. Existing clients that omit it will be rejected.`
          )
        : nonBreaking(
            `Parameter "${field}" on ${where} became optional. Clients that do send it are unaffected.`
          );
    case 'PARAMETER_TYPE_CHANGED':
      return breaking(
        `Parameter "${field}" on ${where} changed type from ${typePhrase(change.before)} to ${typePhrase(change.after)}. Clients sending the previous type may no longer be accepted.`
      );
    case 'PARAMETER_ENUM_CHANGED': {
      const { removed, added } = enumDiff(change.before.enum, change.after.enum);
      if (removed.length > 0) {
        return breaking(
          `Request enum value(s) ${valuesPhrase(removed)} for parameter "${field}" on ${where} were removed. Clients that send those values will be rejected.`
        );
      }
      return nonBreaking(
        `Request enum value(s) ${valuesPhrase(added)} for parameter "${field}" on ${where} were added. Values accepted before are still accepted.`
      );
    }

    // ------------------------------------------------------------------
    // Request body
    // ------------------------------------------------------------------
    case 'REQUEST_BODY_REMOVED':
      return breaking(
        `The request body on ${where} was removed. Clients that send a body may be rejected or have it ignored.`
      );
    case 'REQUEST_BODY_REQUIREDNESS_CHANGED':
      return change.after.required
        ? breaking(
            `The request body on ${where} became required. Clients that call it without a body will be rejected.`
          )
        : nonBreaking(
            `The request body on ${where} became optional. Clients that do send a body are unaffected.`
          );
    case 'REQUEST_BODY_ADDED':
      return unknown(
        `A request body was added to ${where}. The initial rule set defines no rule for adding a request body to an operation that had none; existing clients may not send a body, so manual review is recommended.`
      );
    case 'REQUEST_CONTENT_TYPE_ADDED':
      return unknown(
        `Content type "${change.after.contentType}" was added to the request body of ${where}. The initial rule set defines no rule for request content type changes; manual review is recommended.`
      );
    case 'REQUEST_CONTENT_TYPE_REMOVED':
      return unknown(
        `Content type "${change.before.contentType}" was removed from the request body of ${where}. The initial rule set defines no rule for request content type changes; manual review is recommended.`
      );

    // ------------------------------------------------------------------
    // Response status codes and content types
    // ------------------------------------------------------------------
    case 'RESPONSE_STATUS_ADDED':
      return nonBreaking(
        `Response status ${statusOf(change)} was added to ${where}. Clients that handle the statuses they already know are unaffected.`
      );
    case 'RESPONSE_STATUS_REMOVED':
      return unknown(
        `Response status ${statusOf(change)} was removed from ${where}. The initial rule set defaults removed response status codes to UNKNOWN; clients that handle or rely on this status may be affected, so manual review is recommended.`
      );
    case 'RESPONSE_CONTENT_TYPE_ADDED':
      return unknown(
        `Content type "${change.after.contentType}" was added to response ${statusOf(change)} of ${where}. The initial rule set defaults added response content types to UNKNOWN; manual review is recommended.`
      );
    case 'RESPONSE_CONTENT_TYPE_REMOVED':
      return unknown(
        `Content type "${change.before.contentType}" was removed from response ${statusOf(change)} of ${where}. The initial rule set defaults removed response content types to UNKNOWN; manual review is recommended.`
      );

    // ------------------------------------------------------------------
    // Schema fields (request and response)
    // ------------------------------------------------------------------
    case 'FIELD_ADDED': {
      const required = change.after?.required === true;
      if (inResponse) {
        return required
          ? unknown(
              `Required response field "${field}" was added to ${where}. The initial rule set classifies added required response fields as UNKNOWN: the schema alone does not establish whether existing consumers can handle a new required response member.`
            )
          : nonBreaking(
              `Optional response field "${field}" was added to ${where}. Consumers that ignore unknown fields are unaffected.`
            );
      }
      return required
        ? breaking(
            `Required request field "${field}" was added to ${where}. Existing clients that do not send it will be rejected.`
          )
        : nonBreaking(
            `Optional request field "${field}" was added to ${where}. Clients that do not send it are unaffected.`
          );
    }
    case 'FIELD_REMOVED':
      return breaking(
        inResponse
          ? `Response field "${field}" was removed from ${where}. Consumers that read this field will no longer receive it.`
          : `Request field "${field}" was removed from ${where}. Clients that send this field may be rejected or have it ignored.`
      );
    case 'FIELD_TYPE_CHANGED':
      return breaking(
        `Field "${field}" on ${where} changed type from ${typePhrase(change.before)} to ${typePhrase(change.after)}. Clients that (de)serialize the previous type will fail.`
      );
    case 'FIELD_REQUIREDNESS_CHANGED': {
      const becameRequired = change.after.required === true;
      if (inResponse) {
        return unknown(
          `Response field "${field}" on ${where} changed from ${change.before.required ? 'required' : 'optional'} to ${becameRequired ? 'required' : 'optional'}. The initial rule set defines no rule for response field requiredness changes; consumers that read this field ${becameRequired ? 'will now always receive it' : 'may now receive undefined'}, so manual review is recommended.`
        );
      }
      return becameRequired
        ? breaking(
            `Request field "${field}" on ${where} became required. Existing clients that omit it will be rejected.`
          )
        : nonBreaking(
            `Request field "${field}" on ${where} became optional. Clients that do send it are unaffected.`
          );
    }
    case 'ENUM_CHANGED': {
      const { removed, added } = enumDiff(change.before.enum, change.after.enum);
      if (inResponse) {
        const parts = [];
        if (removed.length > 0) parts.push(`value(s) ${valuesPhrase(removed)} removed`);
        if (added.length > 0) parts.push(`value(s) ${valuesPhrase(added)} added`);
        return unknown(
          `Response enum field "${field}" on ${where} changed (${parts.join('; ') || 'enum changed'}). The initial rule set defaults response enum changes to UNKNOWN; consumers that branch on these values may need updates, so manual review is recommended.`
        );
      }
      if (removed.length > 0) {
        return breaking(
          `Request enum field "${field}" on ${where} removed value(s) ${valuesPhrase(removed)}${
            added.length > 0 ? ` and added ${valuesPhrase(added)}` : ''
          }. Clients that send the removed values will be rejected.`
        );
      }
      return nonBreaking(
        `Request enum field "${field}" on ${where} added value(s) ${valuesPhrase(
          added
        )} without removing accepted values. Previously accepted requests are still accepted.`
      );
    }
    case 'NULLABLE_CHANGED':
      return unknown(
        `Field "${field}" on ${where} changed from ${change.before.nullable ? 'nullable' : 'non-nullable'} to ${change.after.nullable ? 'nullable' : 'non-nullable'}. The initial rule set defines no rule for nullability changes; manual review is recommended.`
      );
    case 'CONSTRAINT_CHANGED': {
      const key = Object.keys(change.before ?? {})[0];
      return unknown(
        `Field "${field}" on ${where} changed constraint "${key}" from ${JSON.stringify(
          change.before?.[key]
        )} to ${JSON.stringify(change.after?.[key])}. The initial rule set defines no rule for constraint changes; manual review is recommended.`
      );
    }
    default:
      return unknown(
        `Change type ${changeType} on ${where} has no rule in the initial rule set; manual review is required.`
      );
  }
}

// ---------------------------------------------------------------------------
// Whole change set
// ---------------------------------------------------------------------------

/**
 * Classify every change in a comparator output and summarise the result.
 *
 * @param {object[]} changes  output of spec-comparator
 * @returns {{
 *   changes: Array<object & { compatibility: string, explanation: string }>,
 *   summary: { total: number, breaking: number, nonBreaking: number, unknown: number },
 *   overallVerdict: string,
 * }}
 */
export function classifyChanges(changes) {
  const classified = changes.map((change) => {
    const { compatibility, explanation } = classifyChange(change);
    return { ...change, compatibility, explanation };
  });

  const summary = {
    total: classified.length,
    breaking: 0,
    nonBreaking: 0,
    unknown: 0,
  };
  for (const change of classified) {
    if (change.compatibility === COMPATIBILITY.BREAKING) summary.breaking += 1;
    else if (change.compatibility === COMPATIBILITY.NON_BREAKING) summary.nonBreaking += 1;
    else summary.unknown += 1;
  }

  const overallVerdict =
    summary.total === 0
      ? OVERALL_VERDICTS.NO_CHANGES
      : summary.breaking > 0
        ? OVERALL_VERDICTS.BREAKING
        : summary.unknown > 0
          ? OVERALL_VERDICTS.UNKNOWN
          : OVERALL_VERDICTS.NON_BREAKING;

  return { changes: classified, summary, overallVerdict };
}

export default classifyChanges;

// Compatibility orchestration: reuses the comparison pipeline (retrieve
// versions, normalize, structural diff) and classifies the result with the
// deterministic rule engine. All Prisma access stays in comparison.service.
import { compareSpecVersions } from './comparison.service.js';
import { classifyChanges } from './compatibility-classifier.js';

/**
 * Compare two stored specification versions and classify every change as
 * BREAKING / NON_BREAKING / UNKNOWN with a plain-language explanation.
 *
 * @throws ApiError 404 SPEC_VERSION_NOT_FOUND when either version is missing
 * @throws ApiError 400 INVALID_COMPARISON when the versions belong to
 *   different services
 * @throws ApiError 400 UNSUPPORTED_SPEC when a stored document contains
 *   constructs the normalizer does not support
 *
 * @returns {Promise<{
 *   serviceId: string,
 *   fromVersion: object,
 *   toVersion: object,
 *   overallVerdict: string,
 *   summary: object,
 *   changes: Array,
 * }>}
 */
export async function runCompatibilityCheck({ fromVersionId, toVersionId }) {
  const report = await compareSpecVersions({ fromVersionId, toVersionId });
  const { changes, summary, overallVerdict } = classifyChanges(report.changes);

  return {
    serviceId: report.serviceId,
    fromVersion: report.fromVersion,
    toVersion: report.toVersion,
    overallVerdict,
    summary,
    changes,
  };
}

export default runCompatibilityCheck;

// HTTP handling for Compatibility Classification. Delegates to
// compatibility.service (which reuses the comparison pipeline); classification
// itself is the pure compatibility-classifier module.
import { runCompatibilityCheck } from '../services/compatibility.service.js';
import { validateDiffQuery } from '../validators/spec.validators.js';
import { ApiError } from '../utils/api-error.js';

// GET /api/compatibility/check?fromVersionId=...&toVersionId=...
// Returns the structural diff between two versions of the same service with
// every change classified as BREAKING / NON_BREAKING / UNKNOWN, plus an
// overall verdict and summary counts.
export async function checkCompatibility(req, res) {
  const result = validateDiffQuery(req.query);
  if (!result.ok) {
    throw new ApiError(400, 'VALIDATION_ERROR', 'Query parameters failed validation', result.errors);
  }

  const report = await runCompatibilityCheck(result.data);

  res.json({
    success: true,
    data: {
      serviceId: report.serviceId,
      fromVersion: report.fromVersion,
      toVersion: report.toVersion,
      overallVerdict: report.overallVerdict,
      summary: report.summary,
      changes: report.changes,
    },
  });
}

export default checkCompatibility;

import { Router } from 'express';
import { checkCompatibility } from '../controllers/compatibility.controller.js';

const router = Router();

router.get('/check', checkCompatibility);

export default router;

