import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { load as loadYaml } from 'js-yaml';
import SwaggerParser from '@apidevtools/swagger-parser';
import { normalizeSpec } from './src/services/spec-normalizer.js';
import { compareSpecs } from './src/services/spec-comparator.js';

const readSpec = (p) =>
  readFileSync(fileURLToPath(new URL(`../specs/${p}`, import.meta.url)), 'utf8');

function norm(p) {
  const text = readSpec(p);
  // Resolve the document first (swagger-parser dereferences $refs). The
  // parser treats strings as file paths, so pass the parsed object.
  return SwaggerParser.parse(loadYaml(text))
    .then((doc) => normalizeSpec(doc))
    .catch((err) => ({ ok: false, errors: [{ code: 'PARSE', message: err.message }] }));
}

