// Throwaway probe of the installed swagger-parser API.
import { load as loadYaml } from 'js-yaml';
import SwaggerParser from '@apidevtools/swagger-parser';

console.log('static:', Object.getOwnPropertyNames(SwaggerParser).filter((n) => !n.startsWith('_')));
console.log('proto:', Object.getOwnPropertyNames(SwaggerParser.prototype).filter((n) => !n.startsWith('_')));

const text = `openapi: 3.0.3
info:
  title: Probe
  version: 1.0.0
paths:
  /a:
    get:
      responses:
        '200':
          description: ok
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/A'
components:
  schemas:
    A:
      type: object
      properties:
        x:
          type: string
`;
const doc = loadYaml(text);

function hasRef(value) {
  if (Array.isArray(value)) return value.some(hasRef);
  if (value && typeof value === 'object') {
    if ('$ref' in value) return true;
    return Object.values(value).some(hasRef);
  }
  return false;
}

for (const name of ['parse', 'validate', 'dereference']) {
  try {
    const fn = SwaggerParser[name];
    if (typeof fn !== 'function') {
      console.log(name, ': not a function');
      continue;
    }
    const out = await fn.call(SwaggerParser, JSON.parse(JSON.stringify(doc)));
    console.log(name, '-> has $ref:', hasRef(out), '| type:', typeof out);
  } catch (err) {
    console.log(name, 'threw:', err.message);
  }
}

