  const { data } = body;

  assert.equal(data.serviceId, quoteService.id);
  assert.equal(data.fromVersion.id, quoteVersions[1].id);
  assert.equal(data.fromVersion.versionLabel, 'v2');
  assert.equal(data.toVersion.versionLabel, 'v3');
  // Stored content is never included.
  assert.ok(!('parsedContent' in data.fromVersion));
  assert.ok(!('originalContent' in data.toVersion));

  assert.equal(typeof data.overallVerdict, 'string');
  assert.equal(data.summary.total, data.changes.length);
  assert.equal(
    data.summary.total,
    data.summary.breaking + data.summary.nonBreaking + data.summary.unknown
  );

  // Every change keeps the comparator fields and gains classification.
  for (const change of data.changes) {
    assert.ok(change.changeType);
    assert.ok(['BREAKING', 'NON_BREAKING', 'UNKNOWN'].includes(change.compatibility));
    assert.ok(typeof change.explanation === 'string' && change.explanation.length > 0);
    assert.ok(typeof change.description === 'string' && change.description.length > 0);
  }
});

test('check: the result is deterministic across repeated calls', async () => {
  const first = await get(checkPath(policyVersions[2].id, policyVersions[3].id));
  const second = await get(checkPath(policyVersions[2].id, policyVersions[3].id));
  assert.deepEqual(first.body.data, second.body.data);
});

