```js
export function fieldStatusInSchema(tokens, rootSchema) {
  let current = rootSchema;
  for (let i = 0; i < tokens.length; i += 1) {
    if (!current || typeof current !== 'object') return { status: 'unverifiable' };
    const { name, array } = tokens[i];
    const props = current.properties;
    if (current.type === 'any') return { status: 'unverifiable' };
    if (current.type === 'array' || (props === undefined && current.type !== 'object')) {
      // no named children resolvable
      return { status: 'not_found' };  // hmm — an array node: can't index named children
    }
    if (props === undefined) {
      // object-typed but no properties declared
      if (current.type === 'object') return { status: 'unverifiable' };
      return { status: 'not_found' };
    }
    if (props[name] === undefined) return { status: 'not_found' };
    current = props[name];
    if (array) {
      if (current.type !== 'array') return { status: 'not_found' };
      current = current.items ?? { type: 'any' };
    }
  }
  return { status: 'exists' };
}
```
