function changeSide(change) {
  // 'request' | 'response' | 'operation'
  if (typeof change.location === 'string' && change.location.startsWith('response.')) return 'response';
  if (change.location === 'response') return 'response'; // RESPONSE_STATUS_*, content type changes
  if (change.location === 'request' || change.location === 'requestBody') return 'request';
  if (change.location === 'parameter') return 'request';
  // endpoint | method | operation
  if (change.changeType === 'OPERATION_ID_CHANGED') return 'operation-neutral';
  return 'operation';
}
function relativeFieldPath(change) {
  const fp = change.fieldPath;
  if (typeof fp !== 'string') return null;
  if (fp.startsWith('request.')) return fp.slice('request.'.length);
  if (fp.startsWith('parameters.')) return fp.slice('parameters.'.length);
  if (fp.startsWith('response.')) {
    const rest = fp.slice('response.'.length); // e.g. '200.quote.premium' or '200[application/json].quote.premium' or '200'
    // strip the status (and optional content type)
    const m = rest.match(/^[^\.\[]+?(?:\[[^\]]+\])?/);
    if (m) return rest.slice(m[0].length).replace(/^\./, '') || null;
    return null;
  }
  return null;
}
