    let relative = null;
    if (fp.startsWith('request.')) relative = fp.slice('request.'.length);
    else if (fp.startsWith('request[')) relative = null; // content type level
    return { side: 'request', kind: relative ? 'field' : 'operation', relative, status: null };
  }
  if (typeof change.location === 'string' && change.location.startsWith('response.')) {
    const status = change.location.slice('response.'.length);
    const is2xx = status.startsWith('2');
    if (!fp) return { side: 'response', kind: 'operation', relative: null, status }; // RESPONSE_STATUS_*
    if (fp.startsWith('response.') ) {
      let rest = fp.slice('response.'.length);
      const m = rest.match(/^[^\.\[]+?(?:\[[^\]]+\])?/);
      rest = m ? rest.slice(m[0].length).replace(/^\./, '') : rest;
      return { side: 'response', kind: rest ? 'field' : 'operation', relative: rest || null, status, is2xx };
    }
  }
  return { side: 'operation', kind: 'operation', relative: null, status: null }; // endpoint/method
}
