// Input validation for the Consumer Registry endpoints.
// Pure functions: no I/O, no Prisma.

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const MAX_NAME_LENGTH = 200;
const MAX_OWNER_LENGTH = 200;
const MAX_DESCRIPTION_LENGTH = 1000;
const MAX_PATH_LENGTH = 500;
const MAX_FIELD_PATH_LENGTH = 300;
const MAX_FIELD_PATHS_PER_DEPENDENCY = 200;
const MAX_DEPENDENCIES_PER_REQUEST = 200;

// Methods the registry accepts. Everything else is rejected explicitly rather
// than stored, so downstream matching can rely on the normalized value.
const SUPPORTED_HTTP_METHODS = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS'];

export function isValidUuid(value) {
  return typeof value === 'string' && UUID_PATTERN.test(value);
}

/**
 * Normalize an HTTP method to uppercase. Returns null when the value is not a
 * supported method (the caller reports the error).
 */
export function normalizeHttpMethod(value) {
  if (typeof value !== 'string') return null;
  const method = value.trim().toUpperCase();
  return SUPPORTED_HTTP_METHODS.includes(method) ? method : null;
}

/**
 * Validates the POST /api/consumers body (consumer registration reuses the
 * Service Registry model, so the fields mirror service registration).
 */
export function validateConsumerRegistration(body) {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return {
      ok: false,
      errors: [{ field: 'body', message: 'Request body must be a JSON object' }],
    };
  }

  const errors = [];

  let name;
  if (body.name === undefined || typeof body.name !== 'string') {
    errors.push({ field: 'name', message: 'name is required and must be a string' });
  } else {
    name = body.name.trim();
    if (name === '') {
      errors.push({ field: 'name', message: 'name must not be empty' });
    } else if (name.length > MAX_NAME_LENGTH) {
      errors.push({ field: 'name', message: `name must be at most ${MAX_NAME_LENGTH} characters` });
    }
  }

  let owner;
  if (body.owner === undefined || typeof body.owner !== 'string') {
    errors.push({ field: 'owner', message: 'owner is required and must be a string' });
  } else {
    owner = body.owner.trim();
    if (owner === '') {
      errors.push({ field: 'owner', message: 'owner must not be empty' });
    } else if (owner.length > MAX_OWNER_LENGTH) {
      errors.push({ field: 'owner', message: `owner must be at most ${MAX_OWNER_LENGTH} characters` });
    }
  }

  let description = null;
  if (body.description !== undefined && body.description !== null) {
    if (typeof body.description !== 'string') {
      errors.push({ field: 'description', message: 'description must be a string' });
    } else {
      description = body.description.trim() || null;
      if (description !== null && description.length > MAX_DESCRIPTION_LENGTH) {
        errors.push({
          field: 'description',
          message: `description must be at most ${MAX_DESCRIPTION_LENGTH} characters`,
        });
      }
    }
  }

  if (errors.length > 0) return { ok: false, errors };
  return { ok: true, data: { name, owner, description } };
}

// Validates one `sends`/`reads` list: optional, but when present it must be an
// array of non-empty strings (the dot-notation field paths are preserved
// verbatim apart from trimming surrounding whitespace).
function validateFieldPaths(value, fieldName, errors, index) {
  if (value === undefined) return undefined;
  if (!Array.isArray(value)) {
    errors.push({
      field: `dependencies[${index}].${fieldName}`,
      message: `${fieldName} must be an array of field-path strings`,
    });
    return [];
  }
  const paths = [];
  for (let i = 0; i < value.length; i += 1) {
    const entry = `dependencies[${index}].${fieldName}[${i}]`;
    if (typeof value[i] !== 'string' || value[i].trim() === '') {
      errors.push({ field: entry, message: 'each field path must be a non-empty string' });
    } else {
      const trimmed = value[i].trim();
      if (trimmed.length > MAX_FIELD_PATH_LENGTH) {
        errors.push({ field: entry, message: `field path must be at most ${MAX_FIELD_PATH_LENGTH} characters` });
      } else {
        paths.push(trimmed);
      }
    }
  }
  if (value.length > MAX_FIELD_PATHS_PER_DEPENDENCY) {
    errors.push({
      field: `dependencies[${index}].${fieldName}`,
      message: `at most ${MAX_FIELD_PATHS_PER_DEPENDENCY} field paths per list`,
    });
  }
  return paths;
}

/**
 * Validates the PUT /api/consumers/:id body, which is a COMPLETE REPLACEMENT
 * of the consumer's dependency declarations:
 *
 *   { dependencies: [ { providerId, method, path, sends?, reads? }, ... ] }
 *
 * providerId references an existing Service record (checked by the service
 * layer). `dependencies: []` means "no dependencies".
 */
export function validateDependencyList(body) {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return {
      ok: false,
      errors: [{ field: 'body', message: 'Request body must be a JSON object' }],
    };
  }
  if (!('dependencies' in body)) {
    return {
      ok: false,
      errors: [{ field: 'dependencies', message: 'dependencies array is required (use [] to clear)' }],
    };
  }

  const errors = [];
  const dependencies = [];

  if (!Array.isArray(body.dependencies)) {
    return { ok: false, errors: [{ field: 'dependencies', message: 'dependencies must be an array' }] };
  }
  if (body.dependencies.length > MAX_DEPENDENCIES_PER_REQUEST) {
    errors.push({
      field: 'dependencies',
      message: `at most ${MAX_DEPENDENCIES_PER_REQUEST} dependencies per request`,
    });
  }

  body.dependencies.forEach((dependency, index) => {
    const prefix = `dependencies[${index}]`;
    if (typeof dependency !== 'object' || dependency === null || Array.isArray(dependency)) {
      errors.push({ field: prefix, message: 'each dependency must be a JSON object' });
      return;
    }

    if (!isValidUuid(dependency.providerId)) {
      errors.push({
        field: `${prefix}.providerId`,
        message: 'providerId must be a valid UUID of a registered service',
      });
    }

    const method = normalizeHttpMethod(dependency.method);
    if (method === null) {
      errors.push({
        field: `${prefix}.method`,
        message: `method must be one of: ${SUPPORTED_HTTP_METHODS.join(', ')}`,
      });
    }

    let path;
    if (typeof dependency.path !== 'string' || dependency.path.trim() === '') {
      errors.push({ field: `${prefix}.path`, message: 'path is required and must be a non-empty string' });
    } else {
      path = dependency.path.trim();
      if (!path.startsWith('/')) {
        errors.push({ field: `${prefix}.path`, message: 'path must start with "/"' });
      } else if (path.length > MAX_PATH_LENGTH) {
        errors.push({ field: `${prefix}.path`, message: `path must be at most ${MAX_PATH_LENGTH} characters` });
      }
    }

    const sends = validateFieldPaths(dependency.sends, 'sends', errors, index);
    const reads = validateFieldPaths(dependency.reads, 'reads', errors, index);

    if (errors.length === 0 || errors.every((e) => !e.field.startsWith(prefix))) {
      dependencies.push({
        providerId: isValidUuid(dependency.providerId) ? dependency.providerId : null,
        method,
        path,
        sends: sends ?? [],
        reads: reads ?? [],
      });
    }
  });

  if (errors.length > 0) return { ok: false, errors };
  return { ok: true, data: { dependencies } };
}

/**
 * Validates the POST /api/consumers/import body. An empty/absent body means
 * "import the starter-kit declaration files from disk".
 */
export function validateImportBody(body) {
  if (body === undefined || body === null || (typeof body === 'object' && Object.keys(body).length === 0)) {
    return { ok: true, data: { declarations: null } };
  }
  if (typeof body !== 'object' || Array.isArray(body)) {
    return { ok: false, errors: [{ field: 'body', message: 'Request body must be a JSON object' }] };
  }
  if (!('declarations' in body)) {
    return {
      ok: false,
      errors: [{ field: 'declarations', message: 'provide a "declarations" array of consumer declarations' }],
    };
  }
  if (!Array.isArray(body.declarations) || body.declarations.length === 0) {
    return {
      ok: false,
      errors: [{ field: 'declarations', message: 'declarations must be a non-empty array' }],
    };
  }
  return { ok: true, data: { declarations: body.declarations } };
}

// Parser for the starter-kit consumer declaration format.
//
// Pure module — no database access, no file I/O. Takes an ALREADY PARSED
// document (YAML/JSON object) and validates its structure, returning the
// declaration in normalized form. The starter-kit files look like this
// (actual fixture shape — field names are preserved verbatim):
//
//   consumer: mobile-app
//   team: Mobile
//   uses:
//   - provider: quote-api
//     method: POST
//     path: /quotes
//     sends:
//     - vehicle.make
//     - rider.age
//     reads:
//     - quoteId
//     - premium.breakdown[].amount
//
// Structural parsing only: this module checks that the document has the
// expected shape. Semantic validation against a provider's published
// specification is a separate step (dependency-validator.js).

import { normalizeHttpMethod } from '../validators/consumer.validators.js';

const MAX_FIELD_PATH_LENGTH = 300;

// Validates one `sends`/`reads` list from a declaration.
function validateFieldList(value, field, prefix, errors) {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) {
    errors.push({ field, message: `${field} must be an array of field-path strings` });
    return [];
  }
  const paths = [];
  for (let i = 0; i < value.length; i += 1) {
    const entryField = `${field}[${i}]`;
    if (typeof value[i] !== 'string' || value[i].trim() === '') {
      errors.push({
        field: entryField,
        message: 'each field path must be a non-empty string',
      });
    } else {
      const trimmed = value[i].trim();
      if (trimmed.length > MAX_FIELD_PATH_LENGTH) {
        errors.push({
          field: entryField,
          message: `field path must be at most ${MAX_FIELD_PATH_LENGTH} characters`,
        });
      } else {
        // Nested and array notation (e.g. "items[].productId") is preserved
        // verbatim — it is the representation the registry stores and the
        // impact analyzer matches on.
        paths.push(trimmed);
      }
    }
  }
  return paths;
}

/**
 * Parse one consumer declaration document.
 *
 * @param {object} document  Parsed YAML/JSON consumer declaration
 * @param {string} sourceName  Identifier of the source (file name), used in
 *   error reporting
 * @returns {{ ok: true, declaration: {
 *   consumer: string,
 *   team: string,
 *   uses: Array<{ provider: string, method: string, path: string,
 *                 sends: string[], reads: string[] }>,
 * }} } | {{ ok: false, errors: Array<{ field: string, message: string }> }}
 */
export function parseConsumerDeclaration(document, sourceName = '(inline)') {
  if (typeof document !== 'object' || document === null || Array.isArray(document)) {
    return {
      ok: false,
      errors: [
        {
          field: `${sourceName}`,
          message: 'consumer declaration must be a mapping with consumer/team/uses keys',
        },
      ],
    };
  }

  const errors = [];

  if (typeof document.consumer !== 'string' || document.consumer.trim() === '') {
    errors.push({
      field: `${sourceName}:consumer`,
      message: 'consumer must be a non-empty service name',
    });
  }

  let team = '';
  if (document.team !== undefined && document.team !== null) {
    if (typeof document.team !== 'string') {
      errors.push({ field: `${sourceName}:team`, message: 'team must be a string' });
    } else {
      team = document.team.trim();
    }
  }

  const uses = [];
  if (document.uses !== undefined && document.uses !== null) {
    if (!Array.isArray(document.uses)) {
      errors.push({ field: `${sourceName}:uses`, message: 'uses must be an array of operation declarations' });
    } else {
      document.uses.forEach((use, index) => {
        const prefix = `${sourceName}:uses[${index}]`;
        if (typeof use !== 'object' || use === null || Array.isArray(use)) {
          errors.push({ field: prefix, message: 'each use must be a mapping with provider/method/path' });
          return;
        }

        if (typeof use.provider !== 'string' || use.provider.trim() === '') {
          errors.push({
            field: `${prefix}:provider`,
            message: 'provider must be a non-empty service name',
          });
        }

        const method = normalizeHttpMethod(use.method);
        if (method === null) {
          errors.push({
            field: `${prefix}:method`,
            message: 'method must be a supported HTTP method (GET, POST, PUT, PATCH, DELETE, HEAD, OPTIONS)',
          });
        }

        let path;
        if (typeof use.path !== 'string' || use.path.trim() === '') {
          errors.push({ field: `${prefix}:path`, message: 'path is required and must be a non-empty string' });
        } else {
          path = use.path.trim();
          if (!path.startsWith('/')) {
            errors.push({ field: `${prefix}:path`, message: 'path must start with "/"' });
          }
        }

        const sends = validateFieldList(use.sends, `${prefix}:sends`, prefix, errors);
        const reads = validateFieldList(use.reads, `${prefix}:reads`, prefix, errors);

        // A single bad entry does not discard the whole declaration: the
        // import reports per-use results, so well-formed uses still import.
        if (
          typeof use.provider === 'string' &&
          use.provider.trim() !== '' &&
          method !== null &&
          typeof use.path === 'string' &&
          use.path.trim().startsWith('/')
        ) {
          uses.push({
            provider: use.provider.trim(),
            method,
            path: use.path.trim(),
            sends,
            reads,
          });
        }
      });
    }
  }

  if (errors.length > 0 && (typeof document.consumer !== 'string' || document.consumer.trim() === '')) {
    // Without a consumer name the declaration cannot be imported at all.
    return { ok: false, errors };
  }

  return {
    ok: true,
    declaration: {
      consumer: document.consumer.trim(),
      team,
      uses,
    },
  };
}

export default parseConsumerDeclaration;

// Semantic validation of consumer dependency declarations against a
// provider's (normalized) OpenAPI representation.
//
// Pure module — no database access. Structural parsing (is the declaration
// well-formed?) lives in consumer-declarations.js; this module answers the
// semantic questions:
//   - does the declared operation exist in the specification?
//   - do the declared request/response field paths exist in the schema?
//
// Path templates are matched positionally (canonicalPath), so a consumer that
// declared /quotes/{id} still matches a specification that renamed the
// parameter to /quotes/{quoteId} — reported as an operation mismatch, not a
// silent pass and not a hard failure.
//
// Field matching is token-aware (segments split on "." with "[]" array
// markers) and never naive string-prefix matching, so "customer.name" does
// not match "customer.nameSuffix".

import { canonicalPath } from './spec-normalizer.js';

/**
 * Match a declared operation ({ method, path }) against the normalized spec's
 * operations.
 *
 * @param {string} method      uppercase HTTP method
 * @param {string} declaredPath  path as the consumer declared it
 * @param {object[]} operations  normalized operations (spec-normalizer output)
 * @returns {{ status: 'exact' | 'mismatch' | 'missing',
 *             operation: object | null }}
 *   exact    — an operation with the same method and the same original path
 *   mismatch — an operation with the same method matches positionally, but
 *              the path parameter names differ
 *   missing  — no operation with that method on that path template
 */
export function matchDeclaredOperation(method, declaredPath, operations) {
  const declaredCanonical = canonicalPath(declaredPath);
  let mismatchCandidate = null;
  for (const operation of operations) {
    if (operation.method !== method) continue;
    if (operation.path === declaredPath) {
      return { status: 'exact', operation };
    }
    if (mismatchCandidate === null && canonicalPath(operation.path) === declaredCanonical) {
      mismatchCandidate = operation;
    }
  }
  if (mismatchCandidate !== null) {
    return { status: 'mismatch', operation: mismatchCandidate };
  }
  return { status: 'missing', operation: null };
}

/**
 * Split a declared field path into segments. "items[].productId" becomes
 * [{ name: 'items', array: true }, { name: 'productId', array: false }].
 */
export function tokenizeFieldPath(fieldPath) {
  return String(fieldPath)
    .split('.')
    .filter((segment) => segment !== '')
    .map((segment) => {
      const array = segment.endsWith('[]');
      const name = array ? segment.slice(0, -2) : segment;
      return { name, array };
    });
}

/**
 * Token-aware prefix relationship between a declared field path and a
 * changed field path (both relative to the schema root).
 *
 * True when one path is a segment-wise prefix of the other:
 *   - changed "customer"        vs declared "customer.address.city" -> true
 *     (removing the parent object affects consumers using descendants)
 *   - changed "customer.address.city" vs declared "customer" -> true
 *     (a consumer that reads the whole object is affected by nested changes)
 *   - changed "customer.name"   vs declared "customer.nameSuffix" -> false
 *     (segment boundary: "name" is not a prefix of "nameSuffix")
 */
export function fieldPathMatches(declaredPath, changedPath) {
  const declared = tokenizeFieldPath(declaredPath);
  const changed = tokenizeFieldPath(changedPath);
  const [shorter, longer] =
    declared.length <= changed.length ? [declared, changed] : [changed, declared];
  for (let i = 0; i < shorter.length; i += 1) {
    if (shorter[i].name !== longer[i].name) return false;
  }
  return true;
}

/**
 * Resolve a declared field path against a normalized schema descriptor.
 *
 * @param {object[]} tokens  tokenizeFieldPath output
 * @param {object|null} rootSchema  normalized schema descriptor (the parent
 *   object that contains the first named property)
 * @returns {{ status: 'exists' | 'not_found' | 'unverifiable' }}
 *   not_found    — the schema is inspectable and the path does not exist
 *   unverifiable — the schema cannot be inspected (absent, type "any", or an
 *                  object with no declared properties); the path neither
 *                  exists nor is absent
 */
export function fieldStatusInSchema(tokens, rootSchema) {
  let current = rootSchema;
  for (const { name, array } of tokens) {
    if (current === null || current === undefined || typeof current !== 'object') {
      return { status: 'unverifiable' };
    }
    if (current.type === 'any') {
      return { status: 'unverifiable' };
    }
    const properties = current.properties;
    if (properties === undefined) {
      // A schema node with no named children: arrays (items), scalars, or an
      // object that declares no properties at all.
      if (current.type === 'object') return { status: 'unverifiable' };
      return { status: 'not_found' };
    }
    if (properties[name] === undefined) {
      return { status: 'not_found' };
    }
    current = properties[name];
    if (array) {
      if (current.type !== 'array') return { status: 'not_found' };
      current = current.items ?? { type: 'any' };
    }
  }
  return { status: 'exists' };
}

// The request-body schema of an operation, if any (first content type that
// carries a schema, application/json preferred).
function requestBodySchema(operation) {
  if (!operation.requestBody || typeof operation.requestBody.content !== 'object') {
    return null;
  }
  const contentTypes = Object.keys(operation.requestBody.content);
  const ordered = ['application/json', ...contentTypes.filter((ct) => ct !== 'application/json')];
  for (const contentType of ordered) {
    const entry = operation.requestBody.content[contentType];
    if (entry && entry.schema) return entry.schema;
  }
  return null;
}

// Schemas carried by all 2xx responses of an operation (all content types).
function responseSchemas(operation) {
  const schemas = [];
  for (const [status, response] of Object.entries(operation.responses ?? {})) {
    if (!status.startsWith('2')) continue;
    for (const entry of Object.values(response.content ?? {})) {
      if (entry && entry.schema) schemas.push(entry.schema);
    }
  }
  return schemas;
}

/**
 * Check a set of declared field paths against one side of an operation.
 *
 * @param {string[]} fieldPaths  declared "sends" or "reads" paths
 * @param {object} operation     normalized operation
 * @param {'request'|'response'} side
 * @returns {Array<{ path: string, status: 'exists' | 'not_found' | 'unverifiable' }>}
 *   Request-side paths also match operation parameter names (path parameters
 *   are declared in `sends`, e.g. "policyId" for /policies/{policyId}).
 */
export function validateDeclaredFields(fieldPaths, operation, side) {
  if (side === 'request') {
    const bodySchema = requestBodySchema(operation);
    const parameterNames = new Set(
      (operation.parameters ?? []).map((parameter) => parameter.name)
    );
    return fieldPaths.map((fieldPath) => {
      if (parameterNames.has(fieldPath)) {
        return { path: fieldPath, status: 'exists' };
      }
      if (bodySchema === null) {
        // No request body at all: a non-parameter field cannot exist.
        return { path: fieldPath, status: 'not_found' };
      }
      const { status } = fieldStatusInSchema(tokenizeFieldPath(fieldPath), bodySchema);
      return { path: fieldPath, status };
    });
  }

  const schemas = responseSchemas(operation);
  return fieldPaths.map((fieldPath) => {
    if (schemas.length === 0) {
      return { path: fieldPath, status: 'not_found' };
    }
    // A field is considered available when it exists in at least one
    // successful response schema of the operation.
    for (const schema of schemas) {
      const { status } = fieldStatusInSchema(tokenizeFieldPath(fieldPath), schema);
      if (status === 'exists') return { path: fieldPath, status };
    }
    return { path: fieldPath, status: 'unverifiable' };
  });
}

/**
 * Validate one dependency declaration against a normalized specification.
 *
 * @param {{ method: string, path: string, sends: string[], reads: string[] }} declaration
 * @param {{ operations: object[] }} normalizedSpec
 * @returns {{
 *   operation: { status: 'exact'|'mismatch'|'missing', matchedPath: string | null },
 *   fields: { request: Array<{path, status}>, response: Array<{path, status}> },
 * }}
 */
export function validateDeclaration(declaration, normalizedSpec) {
  const operations = normalizedSpec.operations ?? [];
  const match = matchDeclaredOperation(declaration.method, declaration.path, operations);

  const fields = { request: [], response: [] };
  if (match.status !== 'missing') {
    fields.request = validateDeclaredFields(declaration.sends ?? [], match.operation, 'request');
    fields.response = validateDeclaredFields(declaration.reads ?? [], match.operation, 'response');
  }

  return {
    operation: {
      status: match.status,
      matchedPath: match.operation ? match.operation.path : null,
    },
    fields,
  };
}

// Consumer Registry business logic.
// All Prisma access for consumers and dependencies lives here; controllers
// never query the database directly.
//
// Consumers are Service records (no duplicate identity model): a service
// "becomes" a consumer when it gains ConsumerDependency rows. The same
// service can be a consumer and a provider at the same time.
import { Prisma } from '@prisma/client';
import prisma from '../database/prisma.js';
import { ApiError } from '../utils/api-error.js';
import { createService } from './service-registry.service.js';
import { normalizeSpec } from './spec-normalizer.js';
import { validateDeclaration } from './dependency-validator.js';

// Dependency row without consumer/provider relations (used in bulk ops).
function dependencyRow(dependency) {
  return {
    id: dependency.id,
    consumerServiceId: dependency.consumerServiceId,
    providerServiceId: dependency.providerServiceId,
    method: dependency.method,
    path: dependency.path,
    sends: dependency.sends,
    reads: dependency.reads,
    createdAt: dependency.createdAt,
    updatedAt: dependency.updatedAt,
  };
}

async function getConsumerOrThrow(id) {
  const service = await prisma.service.findUnique({ where: { id } });
  if (!service) {
    throw new ApiError(404, 'CONSUMER_NOT_FOUND', `Consumer (service) with id "${id}" was not found`);
  }
  return service;
}

/**
 * Register a consumer. Reuses the Service Registry model: a consumer is a
 * service record. Returns the created service.
 */
export async function registerConsumer({ name, owner, description }) {
  return createService({ name, owner, description }); // 409 DUPLICATE_SERVICE on duplicate
}

/**
 * List all services that have at least one dependency declaration (i.e. act
 * as a consumer), with their dependencies grouped by provider.
 */
export async function listConsumers() {
  const services = await prisma.service.findMany({
    where: { consumerDependencies: { some: {} } },
    include: {
      consumerDependencies: {
        include: { provider: { select: { id: true, name: true } } },
      },
      providedDependencies: {
        include: { consumer: { select: { id: true, name: true } } },
      },
    },
    orderBy: { name: 'asc' },
  });

  return services.map((service) => {
    const providers = new Map();
    for (const dependency of service.consumerDependencies) {
      const entry = providers.get(dependency.providerServiceId) ?? {
        id: dependency.provider.id,
        name: dependency.provider.name,
        dependencyCount: 0,
      };
      entry.dependencyCount += 1;
      providers.set(dependency.providerServiceId, entry);
    }
    const consumedBy = new Map();
    for (const dependency of service.providedDependencies) {
      const entry = consumedBy.get(dependency.consumerServiceId) ?? {
        id: dependency.consumer.id,
        name: dependency.consumer.name,
        dependencyCount: 0,
      };
      entry.dependencyCount += 1;
      consumedBy.set(dependency.consumerServiceId, entry);
    }
    return {
      id: service.id,
      name: service.name,
      owner: service.owner,
      description: service.description,
      dependencyCount: service.consumerDependencies.length,
      providers: [...providers.values()],
      uses: service.consumerDependencies.map(dependencyRow),
      consumedBy: [...consumedBy.values()],
      createdAt: service.createdAt,
      updatedAt: service.updatedAt,
    };
  });
}

/**
 * One consumer's record plus the dependencies it declares (as consumer) and
 * the dependencies other services declare against it (as provider).
 */
export async function getConsumer(id) {
  const service = await getConsumerOrThrow(id);
  const [consumerDependencies, providedDependencies] = await Promise.all([
    prisma.consumerDependency.findMany({
      where: { consumerServiceId: id },
      include: { provider: { select: { id: true, name: true } } },
    }),
    prisma.consumerDependency.findMany({
      where: { providerServiceId: id },
      include: { consumer: { select: { id: true, name: true } } },
    }),
  ]);

  return {
    id: service.id,
    name: service.name,
    owner: service.owner,
    description: service.description,
    uses: consumerDependencies.map(dependencyRow),
    consumedBy: providedDependencies.map((dependency) => ({
      ...dependencyRow(dependency),
      consumerName: dependency.consumer.name,
    })),
    createdAt: service.createdAt,
    updatedAt: service.updatedAt,
  };
}

/**
 * REPLACE all dependency declarations of a consumer.
 *
 * Semantics (documented behavior): the request body is the complete,
 * authoritative set of the consumer's dependencies.
 *   - dependencies present in the request are upserted (sends/reads are
 *     updated to the declared values);
 *   - existing dependencies NOT present in the request are deleted.
 * An empty array clears every dependency.
 */
export async function replaceDependencies(consumerId, dependencies) {
  const consumer = await getConsumerOrThrow(consumerId);

  // Every referenced provider must exist.
  const providerIds = [...new Set(dependencies.map((d) => d.providerId))];
  const providers = await prisma.service.findMany({
    where: { id: { in: providerIds } },
    select: { id: true, name: true },
  });
  const found = new Set(providers.map((p) => p.id));
  const missing = [...new Set(dependencies.map((d) => d.providerId))].filter((id) => !found.has(id));
  if (missing.length > 0) {
    const details = await prisma.consumerDependency.findMany({
      where: { consumerServiceId: consumerId },
      select: { id: true },
    });
    void details;
    throw new ApiError(
      400,
      'PROVIDER_NOT_FOUND',
      'One or more referenced provider services do not exist',
      { missingProviderIds: missing }
    );
  }

  await prisma.$transaction(async (tx) => {
    const keep = dependencies.map((d) => ({
      consumerServiceId: consumerId,
      providerServiceId: d.providerId,
      method: d.method,
      path: d.path,
    }));
    if (keep.length > 0) {
      await tx.consumerDependency.deleteMany({
        where: { consumerServiceId, NOT: { OR: keep } },
      });
    } else {
      await tx.consumerDependency.deleteMany({ where: { consumerServiceId: consumerId } });
    }

    for (const dependency of dependencies) {
      await tx.consumerDependency.upsert({
        where: {
          consumerServiceId_providerServiceId_method_path: {
            consumerServiceId: consumerId,
            providerServiceId: dependency.providerId,
            method: dependency.method,
            path: dependency.path,
          },
        },
        create: {
          consumerServiceId: consumerId,
          providerServiceId: dependency.providerId,
          method: dependency.method,
          path: dependency.path,
          sends: dependency.sends,
          reads: dependency.reads,
        },
        update: {
          sends: dependency.sends,
          reads: dependency.reads,
        },
      });
    }
  });

  return getConsumer(consumerId);
}

/**
 * All registered consumers that declare dependencies on a provider service,
 * grouped per consumer.
 */
export async function listProviderConsumers(providerId) {
  const provider = await prisma.service.findUnique({ where: { id: providerId } });
  if (!provider) {
    throw new ApiError(404, 'SERVICE_NOT_FOUND', `Service with id "${providerId}" was not found`);
  }

  const dependencies = await prisma.consumerDependency.findMany({
    where: { providerServiceId: providerId },
    include: { consumer: { select: { id: true, name: true, owner: true } } },
  });

  const byConsumer = new Map();
  for (const dependency of dependencies) {
    const entry = byConsumer.get(dependency.consumerServiceId) ?? {
      id: dependency.consumer.id,
      name: dependency.consumer.name,
      owner: dependency.consumer.owner,
      dependencies: [],
    };
    entry.dependencies.push(dependencyRow(dependency));
    byConsumer.set(dependency.consumerServiceId, entry);
  }

  return {
    provider: { id: provider.id, name: provider.name, owner: provider.owner },
    consumers: [...byConsumer.values()].sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0)),
  };
}

// ---------------------------------------------------------------------------
// Import
// ---------------------------------------------------------------------------

// The provider's latest published version, if any (the baseline a declaration
// is validated against — the same convention the publish flow uses).
async function getPublishedVersion(serviceId) {
  return prisma.apiVersion.findFirst({
    where: { serviceId, status: 'PUBLISHED' },
    orderBy: { createdAt: 'desc' },
  });
}

function fieldIssues(fieldResults, side) {
  return fieldResults
    .filter((field) => field.status === 'not_found')
    .map((field) => ({
      kind: 'field',
      side,
      field: field.path,
      message: `field path "${field.path}" is not present in the published ${side === 'request' ? 'request' : 'response'} schema`,
    }));
}

function useValidationResult(declaration, result) {
  const issues = [];
  let status;

  if (result.operation.status === 'missing') {
    status = 'invalid_operation';
    issues.push({
      kind: 'operation',
      side: null,
      field: `${declaration.method} ${declaration.path}`,
      message: `operation ${declaration.method} ${declaration.path} does not exist in the published specification`,
    });
    return { status, issues };
  }

  const requestIssues = fieldIssues(result.fields.request, 'request');
  const responseIssues = fieldIssues(result.fields.response, 'response');
  const unverifiable = [
    ...result.fields.request.filter((f) => f.status === 'unverifiable'),
    ...result.fields.response.filter((f) => f.status === 'unverifiable'),
  ].map((f) => ({
    kind: 'unverifiable',
    side: null,
    field: f.path,
    message: `field path "${f.path}" could not be verified against the schema`,
  }));

  if (result.operation.status === 'mismatch') {
    status = 'operation_mismatch';
    issues.push({
      kind: 'operation',
      side: null,
      field: `${declaration.method} ${declaration.path}`,
      message: `declared path ${declaration.path} does not exist as written; the published specification has ${declaration.method} ${result.operation.matchedPath} (path parameter names differ)`,
    });
  } else if (requestIssues.length > 0 || responseIssues.length > 0) {
    status = 'field_mismatches';
  } else {
    status = 'validated';
  }

  return { status, issues: [...issues, ...requestIssues, ...responseIssues, ...unverifiable] };
}

/**
 * Import consumer declarations (from starter-kit files or the request body).
 * Idempotent: consumer services are upserted by name, provider references are
 * resolved by name (unresolved providers are reported, never created), and
 * dependencies are upserted on their unique (consumer, provider, method,
 * path) key — importing the same declarations twice creates no duplicates.
 */
export async function importDeclarations(declarations, { source = 'request-body' } = {}) {
  const report = {
    source,
    declarationsProcessed: 0,
    consumersCreated: 0,
    consumersExisting: 0,
    dependenciesUpserted: 0,
    unresolvedProviders: [],
    declarations: [],
  };

  for (const declaration of declarations) {
    report.declarationsProcessed += 1;
    const entry = {
      source: declaration.source ?? null,
      consumer: declaration.consumer,
      team: declaration.team ?? null,
      consumerServiceId: null,
      status: 'ok',
      uses: [],
    };
    report.declarations.push(entry);

    // 1. Consumer: upsert the Service record by name.
    const existingConsumer = await prisma.service.findUnique({
      where: { name: declaration.consumer },
    });
    if (existingConsumer) {
      entry.consumerServiceId = existingConsumer.id;
      report.consumersExisting += 1;
    } else {
      try {
        const created = await prisma.service.create({
          data: {
            name: declaration.consumer,
            owner: declaration.team || 'Starter Kit',
            description: declaration.team ? `Consumer of API operations (team: ${declaration.team})` : null,
          },
        });
        entry.consumerServiceId = created.id;
        report.consumersCreated += 1;
      } catch (err) {
        if (err instanceof Prisma.PrismaClientKnownRequestError && err.code === 'P2002') {
          // Lost a race: another import created it concurrently.
          const raced = await prisma.service.findUnique({ where: { name: declaration.consumer } });
          entry.consumerServiceId = raced?.id ?? null;
          report.consumersExisting += 1;
        } else {
          throw err;
        }
      }
    }

    // 2. Resolve provider references by name.
    const providerNames = [...new Set(declaration.uses.map((use) => use.provider))];
    const providers = await prisma.service.findMany({
      where: { name: { in: providerNames } },
      select: { id: true, name: true },
    });
    const providerByName = new Map(providers.map((p) => [p.name, p]));

    const usesToImport = [];
    for (const use of declaration.uses) {
      const provider = providerByName.get(use.provider);
      if (!provider) {
        entry.status = entry.status === 'ok' ? 'unresolved' : entry.status;
        report.unresolvedProviders.push({ provider: use.provider, declaredBy: declaration.consumer });
        entry.uses.push({
          method: use.method,
          path: use.path,
          status: 'unresolved_provider',
          issues: [
            {
              kind: 'provider',
              side: null,
              field: use.provider,
              message: `provider "${use.provider}" is not registered; the declaration was not imported (providers are never created implicitly)`,
            },
          ],
        });
        continue;
      }
      usesToImport.push({ use, provider });
    }

    // 3. Per-provider validation context: latest published specification.
    const validationCache = new Map(); // providerId -> 'pending' | {spec}
    for (const { use, provider } of usesToImport) {
      if (!validationCache.has(provider.id)) {
        const published = await getPublishedVersion(provider.id);
        if (!published) {
          validationCache.set(provider.id, 'pending');
        } else {
          const normalized = normalizeSpec(published.parsedContent);
          validationCache.set(
            provider.id,
            normalized.ok ? { spec: normalized.spec, versionLabel: published.versionLabel } : null
          );
        }
      }
      const context = validationCache.get(provider.id);

      let useResult;
      if (context === 'pending') {
        // No published specification yet: preserve the declaration and say
        // validation is pending.
        useResult = {
          status: 'pending_validation',
          issues: [
            {
              kind: 'validation',
              side: null,
              field: `${use.method} ${use.path}`,
              message: 'provider has no published specification yet; validation is pending',
            },
          ],
        };
      } else if (context === null) {
        // A published spec exists but cannot be normalized: report it, keep
        // the declaration.
        useResult = {
          status: 'pending_validation',
          issues: [
            {
              kind: 'validation',
              side: null,
              field: `${use.method} ${use.path}`,
              message: 'published specification could not be normalized; validation is pending',
            },
          ],
        };
      } else {
        const result = validateDeclaration(use, context.spec);
        useResult = useValidationResult(use, result);
      }

      entry.uses.push({
        provider: provider.name,
        method: use.method,
        path: use.path,
        ...useResult,
      });

      await prisma.consumerDependency.upsert({
        where: {
          consumerServiceId_providerServiceId_method_path: {
            consumerServiceId: entry.consumerServiceId,
            providerServiceId: provider.id,
            method: use.method,
            path: use.path,
          },
        },
        create: {
          consumerServiceId: entry.consumerServiceId,
          providerServiceId: provider.id,
          method: use.method,
          path: use.path,
          sends: use.sends,
          reads: use.reads,
        },
        update: { sends: use.sends, reads: use.reads },
      });
      report.dependenciesUpserted += 1;
    }

    if (entry.status === 'ok' && entry.uses.length === 0) entry.status = 'no_uses';
  }

  return report;
}

