// Import mechanism for the starter-kit consumer declarations.
//
// The starter kit ships hand-written YAML declaration files (read-only
// inputs, never modified). This module locates them, parses them, and hands
// them to the consumer service layer, which upserts services and
// dependencies and reports per-declaration validation results.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { load as loadYaml } from 'js-yaml';
import { parseConsumerDeclaration } from './consumer-declarations.js';
import { importDeclarations } from './consumer.service.js';

// The declaration files live in <repo-root>/consumers, three levels above
// this file (backend/src/services -> backend -> repo root).
export function defaultDeclarationsDir() {
  return path.resolve(fileURLToPath(new URL('../../../consumers', import.meta.url)));
}

/**
 * Load and parse every *.yaml consumer declaration in a directory.
 *
 * @returns {Array<{ file: string, ok: boolean, declaration?: object,
 *                   errors?: Array<{field, message}> }>}
 */
export function loadDeclarationsFromDir(dir = defaultDeclarationsDir()) {
  let entries;
  try {
    entries = fs.readdirSync(dir);
  } catch (err) {
    throw new Error(`Could not read consumer declarations directory "${dir}": ${err.message}`);
  }

  const results = [];
  for (const file of entries.sort()) {
    if (!file.endsWith('.yaml') && !file.endsWith('.yml')) continue;
    const filePath = path.join(dir, file);
    let document;
    try {
      document = loadYaml(fs.readFileSync(filePath, 'utf8'));
    } catch (err) {
      results.push({
        file,
        ok: false,
        errors: [{ field: file, message: `YAML parse error: ${err.message.split('\n')[0]}` }],
      });
      continue;
    }
    const parsed = parseConsumerDeclaration(document, file);
    if (!parsed.ok) {
      results.push({ file, ok: false, errors: parsed.errors });
      continue;
    }
    results.push({ file, ok: true, declaration: { ...parsed.declaration, source: file } });
  }
  return results;
}

/**
 * Import all starter-kit declarations from disk. Malformed files are
 * reported in the result without aborting the import of the others.
 */
export async function importStarterKitDeclarations(dir = defaultDeclarationsDir()) {
  const loaded = loadDeclarationsFromDir(dir);

  const report = {
    source: 'starter-kit',
    declarationsProcessed: loaded.length,
    consumersCreated: 0,
    consumersExisting: 0,
    dependenciesUpserted: 0,
    unresolvedProviders: [],
    declarations: [],
  };

  const valid = [];
  for (const result of loaded) {
    if (result.ok) {
      valid.push(result.declaration);
    } else {
      report.declarations.push({
        source: result.file,
        consumer: null,
        team: null,
        consumerServiceId: null,
        status: 'parse_error',
        errors: result.errors,
        uses: [],
      });
    }
  }

  if (valid.length > 0) {
    const imported = await importDeclarations(valid, { source: 'starter-kit' });
    report.consumersCreated = imported.consumersCreated;
    report.consumersExisting = imported.consumersExisting;
    report.dependenciesUpserted = imported.dependenciesUpserted;
    report.unresolvedProviders = imported.unresolvedProviders;
    report.declarations.push(...imported.declarations);
  }

  // Deterministic order by source.
  report.declarations.sort((a, b) => String(a.source ?? '').localeCompare(String(b.source ?? '')));
  return report;
}

// HTTP handling for the Consumer Registry. Delegates all business logic and
// database access to the service layer.
import {
  registerConsumer,
  listConsumers,
  getConsumer,
  replaceDependencies,
  listProviderConsumers,
  importDeclarations,
} from '../services/consumer.service.js';
import { importStarterKitDeclarations } from '../services/consumer-importer.js';
import {
  validateConsumerRegistration,
  validateDependencyList,
  validateImportBody,
  isValidUuid,
} from '../validators/consumer.validators.js';
import { ApiError } from '../utils/api-error.js';

// GET /api/consumers — every registered consumer with its dependencies.
export async function listAllConsumers(req, res) {
  const consumers = await listConsumers();
  res.json({ success: true, data: { consumers } });
}

// POST /api/consumers — register a consumer (a Service record).
export async function registerConsumerEndpoint(req, res) {
  const result = validateConsumerRegistration(req.body);
  if (!result.ok) {
    throw new ApiError(400, 'VALIDATION_ERROR', 'Request body failed validation', result.errors);
  }
  const consumer = await registerConsumer(result.data);
  res.status(201).json({ success: true, data: consumer });
}

// GET /api/consumers/:id — one consumer, its declared dependencies (uses)
// and the dependencies other services declare against it (consumedBy).
export async function getConsumerById(req, res) {
  const { id } = req.params;
  if (!isValidUuid(id)) {
    throw new ApiError(400, 'INVALID_ID', 'id must be a valid UUID');
  }
  const consumer = await getConsumer(id);
  res.json({ success: true, data: consumer });
}

// PUT /api/consumers/:id — REPLACE the consumer's dependency declarations.
// The body is the complete set of dependencies: entries are upserted and
// existing dependencies missing from the body are deleted.
export async function updateConsumerDependencies(req, res) {
  const { id } = req.params;
  if (!isValidUuid(id)) {
    throw new ApiError(400, 'INVALID_ID', 'id must be a valid UUID');
  }
  const result = validateDependencyList(req.body);
  if (!result.ok) {
    throw new ApiError(400, 'VALIDATION_ERROR', 'Request body failed validation', result.errors);
  }
  const consumer = await replaceDependencies(id, result.data.dependencies);
  res.json({ success: true, data: consumer });
}

// POST /api/consumers/import — import consumer declarations.
// Empty body: import the starter-kit files from disk.
// Body { declarations: [...] }: import the supplied declarations (each in
// the starter-kit shape { consumer, team, uses: [...] }).
export async function importConsumerDeclarations(req, res) {
  const result = validateImportBody(req.body);
  if (!result.ok) {
    throw new ApiError(400, 'VALIDATION_ERROR', 'Request body failed validation', result.errors);
  }

  let report;
  if (result.data.declarations === null) {
    report = await importStarterKitDeclarations();
  } else {
    // Parse each supplied declaration; malformed ones are reported, valid
    // ones are imported.
    const { parseConsumerDeclaration } = await import('../services/consumer-declarations.js');
    const valid = [];
    const report = {
      source: 'request-body',
      declarationsProcessed: result.data.declarations.length,
      consumersCreated: 0,
      consumersExisting: 0,
      dependenciesUpserted: 0,
      unresolvedProviders: [],
      declarations: [],
    };
    result.data.declarations.forEach((declaration, index) => {
      const parsed = parseConsumerDeclaration(declaration, `declarations[${index}]`);
      if (parsed.ok) {
        valid.push({ ...parsed.declaration, source: `declarations[${index}]` });
      } else {
        report.declarations.push({
          source: `declarations[${index}]`,
          consumer:
            declaration && typeof declaration.consumer === 'string' ? declaration.consumer : null,
          team: null,
          consumerServiceId: null,
          status: 'parse_error',
          errors: parsed.errors,
          uses: [],
        });
      }
    });
    if (valid.length > 0) {
      const imported = await importDeclarations(valid, { source: 'request-body' });
      report.consumersCreated = imported.consumersCreated;
      report.consumersExisting = imported.consumersExisting;
      report.dependenciesUpserted = imported.dependenciesUpserted;
      report.unresolvedProviders = imported.unresolvedProviders;
      report.declarations.push(...imported.declarations);
    }
    report.declarations.sort((a, b) => String(a.source ?? '').localeCompare(String(b.source ?? '')));
    report = report;
  }

  res.json({ success: true, data: report });
}

// GET /api/services/:id/consumers — registered consumers depending on this
// provider service (mounted on the /api/services router).
export async function getProviderConsumers(req, res) {
  const { id } = req.params;
  if (!isValidUuid(id)) {
    throw new ApiError(400, 'INVALID_ID', 'id must be a valid UUID');
  }
  const result = await listProviderConsumers(id);
  res.json({ success: true, data: result });
}

